QB.add(64,[{"n":1,"q":"A 68-year-old female presents with a new-onset severe headache, scalp tenderness, and jaw pain while chewing. Laboratory investigations reveal ESR 85 mm/hr, CRP 45 mg/L, and mild normochromic anemia. A biopsy of the temporal artery shows panarteritis with inflammatory mononuclear cell infiltrates and giant cell formation. In the analysis of T cells from the arterial lesion, which cytokines are primarily produced and play a crucial role in disease progression?","o":[{"t":"IL-4 and IL-5"},{"t":"IL-2 and IFN-g"},{"t":"IL-10 and TGF-b"},{"t":"IL-6 and TNF-a"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) IL-2 and IFN-g"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"The symptoms suggest the diagnosis of Giant Cell Arteritis (GCA)"},{"k":"b","l":0,"v":"IL-2 and IFN-g are the predominant cytokines produced by T cells in GCA lesions"},{"k":"b","l":0,"v":"IFN-g specifically has been implicated in disease progression to arteritis"},{"k":"b","l":0,"v":"These cytokines reflect the TH1-mediated immune response in GCA pathogenesis"},{"k":"p","l":0,"v":"Giant Cell Arteritis (GCA):"},{"k":"b","l":0,"v":"GCA is an inflammatory condition of medium and large-sized arteries"},{"k":"b","l":0,"v":"Earlier called temporal arteritis due to temporal artery involvement"},{"k":"b","l":0,"v":"It's a systemic vasculitis affecting carotid artery branches and the aorta and its major branches"},{"k":"b","l":0,"v":"Occurs almost exclusively in people over 50 years"},{"k":"b","l":0,"v":"Shows strong female predominance"},{"k":"b","l":0,"v":"Genetic associations: HLA-DR4 and HLA-DRB1*04 variants"},{"k":"b","l":0,"v":"Strong association with polymyalgia rheumatica (PMR) : 40-50% of GCA patients have PMR 10-20% of PMR patients later develop GCA"},{"k":"b","l":0,"v":"40-50% of GCA patients have PMR"},{"k":"b","l":0,"v":"10-20% of PMR patients later develop GCA"},{"k":"b","l":0,"v":"40-50% of GCA patients have PMR"},{"k":"b","l":0,"v":"10-20% of PMR patients later develop GCA"},{"k":"p","l":0,"v":"Histopathology :"},{"k":"b","l":0,"v":"Panarteritis (inflammation of the entire vessel wall)"},{"k":"b","l":0,"v":"Mononuclear cell infiltrates"},{"k":"b","l":0,"v":"Giant cell formation"},{"k":"b","l":0,"v":"Intimal proliferation"},{"k":"b","l":0,"v":"Internal elastic lamina fragmentation"},{"k":"img","v":8855},{"k":"p","l":0,"v":"Pathogenesis :"},{"k":"b","l":0,"v":"Antigen-driven disease"},{"k":"b","l":0,"v":"Involves T lymphocytes, macrophages, and dendritic cells"},{"k":"b","l":0,"v":"CD4+ T cells enter through vasa vasorum"},{"k":"b","l":0,"v":"Two key T cell lineages: TH1 (IFN-g) and TH17 cells"},{"k":"p","l":0,"v":"Clinical Manifestations:"},{"k":"b","l":0,"v":"Fever"},{"k":"b","l":0,"v":"Headaches"},{"k":"b","l":0,"v":"Malaise and fatigue"},{"k":"b","l":0,"v":"Anorexia and weight loss"},{"k":"b","l":0,"v":"Sweats"},{"k":"b","l":0,"v":"Arthralgias"},{"k":"b","l":0,"v":"Scalp pain"},{"k":"b","l":0,"v":"Jaw claudication"},{"k":"b","l":0,"v":"Ischemic optic neuropathy leading to blindness"},{"k":"b","l":0,"v":"Strokes"},{"k":"b","l":0,"v":"Large vessel complications (in up to 1/3rd of patients): Subclavian artery stenosis Aortic aneurysms (thoracic > abdominal) Risk of aortic rupture or dissection"},{"k":"b","l":0,"v":"Subclavian artery stenosis"},{"k":"b","l":0,"v":"Aortic aneurysms (thoracic > abdominal)"},{"k":"b","l":0,"v":"Risk of aortic rupture or dissection"},{"k":"b","l":0,"v":"Subclavian artery stenosis"},{"k":"b","l":0,"v":"Aortic aneurysms (thoracic > abdominal)"},{"k":"b","l":0,"v":"Risk of aortic rupture or dissection"},{"k":"p","l":0,"v":"IL-4 and IL-5 (Option A) are typically associated with TH2 responses, not characteristic of GCA IL-10 and TGF-b (Option C) are primarily immunoregulatory cytokines"},{"k":"p","l":0,"v":"While these may be present, IL-6 and TNF-a (Option D) are not the predominant T cell-produced cytokines in GCA lesions."}]},{"n":2,"q":"A 72-year-old female presents with a new-onset headache, jaw claudication, and visual symptoms. Her ESR is 92 mm/hr and CRP is elevated. Temporal artery biopsy is planned, but immediate treatment is necessary. Which of the following is the most appropriate initial management strategy?","o":[{"t":"Wait for biopsy results before starting any treatment"},{"t":"Start prednisone 40-60 mg/day immediately"},{"t":"Begin methotrexate and low-dose aspirin"},{"t":"Start tocilizumab alone"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Start prednisone 40-60 mg/day immediately"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"The symptoms of new-onset headache, jaw claudication, and visual symptoms point towards Giant Cell Arteritis"},{"k":"b","l":0,"v":"Treatment should not be delayed pending diagnostic studies"},{"k":"b","l":0,"v":"Initial therapy is prednisone 40-60 mg/day for ~1 month"},{"k":"b","l":0,"v":"Early treatment is crucial to prevent vision loss"},{"k":"b","l":0,"v":"Temporal artery biopsy can remain positive for ~14 days after starting steroids"},{"k":"p","l":0,"v":"GCA:"},{"k":"p","l":0,"v":"Diagnostic Approach:"},{"k":"p","l":0,"v":"1. Clinical Features + Labs:"},{"k":"b","l":0,"v":"Age >50 years"},{"k":"b","l":0,"v":"Fever, anemia, high ESR/CRP"},{"k":"b","l":0,"v":"Headache, jaw claudication"},{"k":"b","l":0,"v":"Vision symptoms"},{"k":"p","l":0,"v":"2. Confirmatory Tests:"},{"k":"b","l":0,"v":"Temporal artery biopsy (3-5 cm segment)"},{"k":"b","l":0,"v":"Serial sectioning due to patchy involvement"},{"k":"b","l":0,"v":"Ultrasonography of the temporal artery"},{"k":"b","l":0,"v":"Vascular imaging (MR/CT) for large vessel involvement"},{"k":"p","l":0,"v":"3. Laboratory Findings:"},{"k":"b","l":0,"v":"Elevated ESR and CRP"},{"k":"b","l":0,"v":"Elevated alkaline phosphatase"},{"k":"b","l":0,"v":"Increased IgG and complement"},{"k":"p","l":0,"v":"Treatment Protocol:"},{"k":"p","l":0,"v":"1. Initial Management:"},{"k":"b","l":0,"v":"Prednisone 40-60 mg/day immediately for 1 month"},{"k":"b","l":0,"v":"IV methylprednisolone 1000 mg daily for 3 days if ocular symptoms"},{"k":"b","l":0,"v":"Aspirin 81 mg daily to reduce cranial ischemic complications"},{"k":"p","l":0,"v":"2. Additional Therapies:"},{"k":"b","l":0,"v":"Tocilizumab (anti-IL-6) FDA approved"},{"k":"b","l":0,"v":"Given as 162 mg SC weekly/biweekly with steroids"},{"k":"b","l":0,"v":"Methotrexate as alternative steroid-sparing agent"},{"k":"p","l":0,"v":"3. Monitoring:"},{"k":"b","l":0,"v":"Treatment typically needed for ‡2 years"},{"k":"b","l":0,"v":"60-85% have symptom recurrence during tapering"},{"k":"b","l":0,"v":"Watch for glucocorticoid toxicity (35-65% of patients)"},{"k":"p","l":0,"v":"Waiting for a biopsy before starting any treatment (Option A) is incorrect as it risks permanent vision loss"},{"k":"p","l":0,"v":"Begin methotrexate and low-dose aspirin (Option C): Methotrexate is not first-line therapy; it's used as a steroid-sparing agent in select cases"},{"k":"p","l":0,"v":"Start Tocilizumab alone (Option D) is used in combination with steroids, not as monotherapy"}]},{"n":3,"q":"A 6-year-old boy presents with a bilateral lower extremity rash that appeared 2 weeks after an upper respiratory tract infection. He also complains of abdominal pain and joint pain. On examination, there is a symmetrically distributed palpable purpuric rash present over both lower extremities, predominantly on the extensor surfaces. Which of the following is the most likely diagnosis based on the clinical presentation and image findings?","o":[{"t":"Immune thrombocytopenic purpura (ITP)"},{"t":"IgA vasculitis (Henoch-Schönlein purpura)"},{"t":"Meningococcemia"},{"t":"Kawasaki disease"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) IgA vasculitis (Henoch-Schönlein purpura)"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"From the given clinical scenario, IgA vasculitis will be the most likely diagnosis."},{"k":"p","l":0,"v":"Age group (4-7 years), classic palpable purpura with lower extremity predominance, post-infectious trigger (upper respiratory infection), associated symptoms (abdominal pain, arthralgias), and symmetric distribution of rash point out to IgA vasculitis."},{"k":"p","l":0,"v":"IgA vasculitis (Henoch-Schönlein purpura):"},{"k":"b","l":0,"v":"The deposited IgA immune complexes activate the alternative complement pathway."},{"k":"b","l":0,"v":"Complement activation promotes inflammation, causing recruitment of neutrophils and other inflammatory cells, which release cytokines and proteolytic enzymes."},{"k":"b","l":0,"v":"Palpable purpura (100%): Vascular inflammation causes palpable purpura."},{"k":"b","l":0,"v":"Arthralgia (75%): Inflammation leads to joint pain and swelling, although typically self-limiting."},{"k":"b","l":0,"v":"Abdominal pain (70%): Vasculitis of intestinal vessels can cause abdominal pain, bleeding, and intussusception."},{"k":"b","l":0,"v":"Renal involvement (10-50%): Immune complex deposition in the glomeruli leads to glomerulonephritis, presenting with hematuria and sometimes proteinuria."},{"k":"p","l":0,"v":"ITP (Option A): It presents with non-palpable purpura, mucosal bleeding, low platelet count, and no systemic symptoms like joint pain or abdominal pain."},{"k":"p","l":0,"v":"Meningococcemia (Option C): It presents acutely with a toxic appearance, rapidly progressive petechiae/purpura, associated with high fever and meningeal signs, not symmetric in distribution."},{"k":"p","l":0,"v":"Kawasaki disease (Option D): It presents with polymorphous rash (not purpuric), characteristic mucosal changes, cervical lymphadenopathy, and coronary artery involvement."}]},{"n":4,"q":"A 7-year-old boy presents with palpable purpura, abdominal pain, and joint pain. Laboratory studies show normal platelet count with elevated IgA levels. Which of the following statements about this condition is incorrect?","o":[{"t":"Renal biopsy is essential for confirming the diagnosis"},{"t":"Glucocorticoids help reduce arthralgias and abdominal discomfort"},{"t":"Glucocorticoids have not proven benefit in treating skin and renal manifestations"},{"t":"Complement levels are typically normal in this condition"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) Renal biopsy is essential for confirming the diagnosis"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The diagnosis of IgA vasculitis (HSP) is primarily based on clinical signs and symptoms. Renal biopsy is rarely needed."},{"k":"p","l":0,"v":"Henoch Schonlein Purpura:"},{"k":"p","l":1,"v":"Diagnostic Presence of two or more of the following: Criteria Palpable purpura without thrombocytopenia"},{"k":"p","l":2,"v":"Patient 20 years or younger at disease onset Bowel angina (diffuse abdominal pain or diagnosis of bowel ischemia) The biopsy showed granulocytes in the walls of small arterioles or venules, and IgA deposits were found in the vessel wall."},{"k":"p","l":1,"v":"Lab Findings Normal complement (Option D ruled out). This is an"},{"k":"p","l":2,"v":"important distinguishing feature from some other vasculitis. Normal platelets Elevated IgA in ~50% Mild leukocytosis Skin biopsy can confirm (shows leukocytoclastic vasculitis with IgA and C3 deposition) Renal biopsy is rarely needed"},{"k":"p","l":1,"v":"Treatment Often self-limiting"},{"k":"p","l":2,"v":"Glucocorticoids (1 mg/kg/day prednisone): (Option B ruled out) Helpful for: edema, joint pain, abdominal pain Not proven for skin/renal disease (Option C ruled out)"}]},{"n":5,"q":"A 19-year-old Asian female presents with persistent malaise, fever, night sweats, and unequal blood pressure readings in both arms (right arm 130/80 mmHg, left arm 100/70 mmHg). ESR is elevated at 85 mm/hr, and MR angiography shows ostial narrowing of the left subclavian artery with pan-arteritis. Which statement describes the pathogenesis and initial management?","o":[{"t":"Primarily intimal disease; start anti-TNF therapy"},{"t":"Panarteritis; tocilizumab superior to steroids"},{"t":"Adventitial inflammation; methotrexate first-line"},{"t":"Panarteritis with intimal proliferation; start prednisone"}],"a":[3],"s":[{"k":"p","l":0,"v":"Correct answer: D) Panarteritis with intimal proliferation; start prednisone"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The patient presents with Takayasu Arteritis ."},{"k":"b","l":0,"v":"Pathology: Pan-arteritis with intimal proliferation"},{"k":"b","l":0,"v":"Initial treatment: glucocorticoids (40-60mg prednisone/day)"},{"k":"b","l":0,"v":"Controls acute inflammation before considering surgery"},{"k":"p","l":0,"v":"Takayasu Arteritis (\"Pulseless disease\"):"},{"k":"p","l":0,"v":"General features:"},{"k":"b","l":0,"v":"Predominantly affects young females (<20 years)"},{"k":"b","l":0,"v":"Vascular Involvement: A leading cause of renal artery stenosis in India Most commonly affects the left subclavian artery Characteristic ostial narrowing vs. diffuse involvement in atherosclerosis"},{"k":"b","l":0,"v":"A leading cause of renal artery stenosis in India"},{"k":"b","l":0,"v":"Most commonly affects the left subclavian artery"},{"k":"b","l":0,"v":"Characteristic ostial narrowing vs. diffuse involvement in atherosclerosis"},{"k":"b","l":0,"v":"A leading cause of renal artery stenosis in India"},{"k":"b","l":0,"v":"Most commonly affects the left subclavian artery"},{"k":"b","l":0,"v":"Characteristic ostial narrowing vs. diffuse involvement in atherosclerosis"},{"k":"p","l":0,"v":"Clinical Features:"},{"k":"p","l":0,"v":"a) Early Phase (Pre-pulseless):"},{"k":"b","l":0,"v":"Systemic symptoms: fever, malaise, night sweats"},{"k":"b","l":0,"v":"Arthralgias, anorexia, weight loss"},{"k":"p","l":0,"v":"b) Vascular Phase:"},{"k":"b","l":0,"v":"Arm claudication"},{"k":"b","l":0,"v":"Unequal blood pressure between arms"},{"k":"b","l":0,"v":"Pulseless disease (difficult to appreciate radial artery)"},{"k":"b","l":0,"v":"Hypertension (32-93%)"},{"k":"p","l":0,"v":"Differential Diagnosis:"},{"k":"b","l":0,"v":"Young female with renal artery stenosis: India: Think Takayasu arteritis USA: Think fibromuscular dysplasia (FMD)"},{"k":"b","l":0,"v":"India: Think Takayasu arteritis"},{"k":"b","l":0,"v":"USA: Think fibromuscular dysplasia (FMD)"},{"k":"b","l":0,"v":"Arm claudication: Rule out neurogenic claudication (cervical disc disease)"},{"k":"b","l":0,"v":"Rule out neurogenic claudication (cervical disc disease)"},{"k":"b","l":0,"v":"India: Think Takayasu arteritis"},{"k":"b","l":0,"v":"USA: Think fibromuscular dysplasia (FMD)"},{"k":"b","l":0,"v":"Rule out neurogenic claudication (cervical disc disease)"},{"k":"p","l":0,"v":"Investigations:"},{"k":"b","l":0,"v":"Mild anemia"},{"k":"b","l":0,"v":"Elevated immunoglobulins"},{"k":"b","l":0,"v":"Investigation of choice: MR angiography (MRA)"},{"k":"b","l":0,"v":"Complete imaging of the aorta and major branches needed"},{"k":"p","l":0,"v":"Management:"},{"k":"p","l":0,"v":"First Line: Steroids (40-60mg prednisone/day)"},{"k":"p","l":0,"v":"Second Line: Methotrexate ( up to 25mg/week) for steroid-refractory cases"},{"k":"p","l":0,"v":"Important Points for Differential Blood Pressure:"},{"k":"b","l":0,"v":"Normal difference between arm-leg BP: <20 mmHg"},{"k":"b","l":0,"v":"Conditions with unequal arm BPs: Takayasu arteritis Supravalvular aortic stenosis with Coanda effect Preductal coarctation of aorta"},{"k":"b","l":0,"v":"Takayasu arteritis"},{"k":"b","l":0,"v":"Supravalvular aortic stenosis with Coanda effect"},{"k":"b","l":0,"v":"Preductal coarctation of aorta"},{"k":"b","l":0,"v":"Takayasu arteritis"},{"k":"b","l":0,"v":"Supravalvular aortic stenosis with Coanda effect"},{"k":"b","l":0,"v":"Preductal coarctation of aorta"},{"k":"p","l":0,"v":"Major complications: Heart failure, stroke, MI, aneurysm rupture, renal failure"},{"k":"p","l":0,"v":"Primarily intimal disease; start anti-TNF therapy (Option A): The disease affects all layers, not just intima. Anti-TNF therapy isn't first-line and lacks randomized trial validation."},{"k":"p","l":0,"v":"Panarteritis; tocilizumab superior to steroids (Option B): While panarteritis is correct, Tocilizumab failed to show superiority in randomized trials."},{"k":"p","l":0,"v":"Adventitial inflammation; methotrexate first-line (Option C): Not limited to adventitia; affects all vessel layers. Methotrexate is the second-line for steroid-refractory cases."}]},{"n":6,"q":"A 4-year-old child presents with fever, rash, and strawberry tongue. The child has circumoral pallor and a sandpaper-like rash. Laboratory investigations reveal elevated inflammatory markers. Which of the following statements is most likely to be true regarding this presentation?","o":[{"t":"IVIG with high-dose aspirin is the first-line treatment"},{"t":"The rash begins over the face and shows circumoral erythema"},{"t":"Throat culture is essential for diagnosis and Penicillin is the treatment of choice"},{"t":"Coronary artery involvement is seen in the majority of untreated cases"}],"a":[2],"s":[{"k":"p","l":0,"v":"Correct answer: C) Throat culture is essential for diagnosis and Penicillin is the treatment of choice"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The clinical presentation suggests scarlet fever with classic features like circumoral pallor, strawberry tongue, and sandpaper rash."},{"k":"b","l":0,"v":"Throat culture for group A streptococcus is diagnostic"},{"k":"b","l":0,"v":"Penicillin is the treatment of choice to prevent complications"},{"k":"b","l":0,"v":"This is primarily a toxin-mediated process from GAS (Group A Streptococci) infection"},{"k":"p","l":0,"v":"Differentials of strawberry tongue with skin rash and fever:"},{"k":"p","l":1,"v":"Feature Kawasaki’s Disease Scarlet Fever"},{"k":"p","l":1,"v":"Cause Etiology unknown; Likely Group A Streptococcus infection"},{"k":"p","l":2,"v":"Immune-Mediated. (Streptococcal pyrogenic exotoxins"},{"k":"p","l":2,"v":"A, B, C)."},{"k":"p","l":1,"v":"Age Gr It primarily affects children, Most common in children aged 2–10 oup Aff 80% of cases in children £5 years years, usually following Group A ected old, streptococcal pharyngitis."},{"k":"p","l":2,"v":"Peak incidence at £2 years."},{"k":"p","l":1,"v":"Main Based on fever lasting ‡5 days + ‡4 Fever, Sympto of 5 principal criteria: Pharyngitis, ms Fever ‡5 days Headache,"},{"k":"p","l":2,"v":"Bilateral conjunctival injection (red Characteristic rash with a eyes) sandpaper-like texture , beginning Oral mucosal changes (strawberry on the face, spreading to the trunk tongue, red lips) and extremities, sparing palms and Rash (polymorphous) soles, followed by desquamation. Extremity changes (swelling, Circumoral pallor, and redness, peeling) Strawberry tongue."},{"k":"p","l":1,"v":"Other Coronary artery aneurysms, Rash accentuates in skin folds Sympto myocarditis, pericarditis, myocardial (Pastia’s lines) , desquamation in ms ischemia, infarction, cardiomegaly. the second week."},{"k":"p","l":1,"v":"Compli Coronary Artery Aneurysms Rheumatic Fever cations Myocardial Infarction Post-Streptococcal Glomerulonephrit"},{"k":"p","l":2,"v":"Thrombosis is Vasculitis."},{"k":"p","l":1,"v":"Diagno Diagnosis is clinical based on Throat culture or RADT (Rapid stic met criteria and confirmed by Antigen Detection Test) for Group A hod echocardiogram for coronary artery Streptococcus confirmation."},{"k":"p","l":2,"v":"changes."},{"k":"p","l":1,"v":"Treatm High-dose IV Immunoglobulin and Antibiotics (penicillin or amoxicillin), ent Aspirin to reduce coronary artery Supportive care for fever and throat"},{"k":"p","l":2,"v":"complications. pain. In severe cases, surgical intervention may be required (e.g., coronary artery bypass grafting)."},{"k":"p","l":0,"v":"IVIG with high-dose aspirin is the first-line treatment (Option A) is incorrect as this is the treatment for Kawasaki disease, not scarlet fever."},{"k":"p","l":0,"v":"The rash begins over the face and shows circumoral erythema (Option B): In scarlet fever, circumoral pallor (not erythema) is characteristic."},{"k":"p","l":0,"v":"Coronary artery involvement in most untreated cases (Option D) is a feature of Kawasaki disease, not scarlet fever."}]},{"n":7,"q":"Match the markers (Column B) with the correct vasculitis (Column A). a. Granulomatosis with Polyangiitis (GPA) 1. C-ANCA b. Polyarteritis Nodosa (PAN) 2. P-ANCA 3. Proteinase-3 4. Myeloperoxidase\na. Granulomatosis with Polyangiitis (GPA) 1. C-ANCA\nb. Polyarteritis Nodosa (PAN) 2. P-ANCA\n3. Proteinase-3\n4. Myeloperoxidase","o":[{"t":"a-1, 4 & b- 2, 3"},{"t":"a-1, 3 & b- 2,4"},{"t":"a- 2, 4 & b-1,3"},{"t":"a- 2, 3 & b-1,4"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) a-1, 3 & b- 2,4"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":1,"v":"Feature Granulomatosis with Polyangiitis Polyarteritis Nodosa"},{"k":"p","l":2,"v":"(GPA)/ Wegener's granulomatosis"},{"k":"p","l":1,"v":"Target Organs Upper respiratory tract Kidney"},{"k":"p","l":2,"v":"Lower respiratory tract Pulmonary arteries Kidneys Multiple organs"},{"k":"p","l":1,"v":"Key Clinical Epistaxis Hematuria Features Sinusitis Digital ulcers/gangrene"},{"k":"p","l":2,"v":"Nasal ulcers Hypertension Hemoptysis MI Lung cavities Stroke Hematuria Livedo reticularis"},{"k":"p","l":1,"v":"Laboratory c-ANCA (antibody against p-ANCA (antibody against Markers Proteinase 3) MPO)"},{"k":"p","l":2,"v":"Proteinase-3 Myeloperoxidase"},{"k":"p","l":1,"v":"Treatment Cyclophosphamide Similar immunosuppression"},{"k":"p","l":2,"v":"Rituximab BP control essential Steroids"},{"k":"p","l":0,"v":"ANCA Type Common Diseases"},{"k":"p","l":0,"v":"p-ANCA Microscopic polyangiitis"},{"k":"p","l":2,"v":"Churg-Strauss syndrome Ulcerative colitis Primary sclerosing cholangitis Crescentic glomerulonephritis"},{"k":"p","l":0,"v":"c-ANCA Wegener's granulomatosis"},{"k":"p","l":0,"v":"Atypical ANCA. IBD (p-ANCA and c-ANCA) Rheumatoid arthritis"}]},{"n":8,"q":"A 45-year-old patient presents with fever, purpura, and arthralgias. Biopsy shows small vessel vasculitis with immune deposits. Lab tests reveal C-ANCA antibodies. Which of the following is most consistent with this clinical picture?","o":[{"t":"Microscopic polyangiitis with segmental necrotizing glomerulonephritis"},{"t":"Granulomatosis with polyangiitis with pauci-immune glomerulonephritis"},{"t":"Churg-Strauss syndrome with peripheral eosinophilia"},{"t":"Mixed cryoglobulinemia with Hepatitis-C"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Granulomatosis with polyangiitis with pauci-immune glomerulonephritis"},{"k":"h","l":0,"v":"Explanation: The case presents classic features of Granulomatosis with polyangiitis (GPA), which are C-ANCA/PR3 positivity and small vessel vasculitis."},{"k":"p","l":0,"v":"The various types of small vessel vasculitis are listed below:"},{"k":"p","l":0,"v":"Microvascular vasculitis"},{"k":"p","l":0,"v":"Disease Key Features Antibodies/Labs Pathology"},{"k":"p","l":0,"v":"Granulomatosis with Pauci-immune PR3-ANCA Granulomatous Polyangiitis (GPA) vasculitis c-ANCA pattern inflammation"},{"k":"p","l":2,"v":"Upper/lower respirato Small vessel vasculitis ry Glomerulonephritis"},{"k":"p","l":0,"v":"Microscopic Polyangiitis Pulmonary-renal MPO-ANCA Necrotizing vasculitis"},{"k":"p","l":2,"v":"syndrome p-ANCA pattern No granulomas No granulomas (Option A ruled out) Segmental necrotizin g GN"},{"k":"p","l":0,"v":"Churg-Strauss (EGPA) Asthma MPO-ANCA Eosinophilic"},{"k":"p","l":2,"v":"Peripheral eosinophili p-ANCA pattern granulomas a (Option C ruled out) Vasculitis Allergic rhinitis"},{"k":"p","l":0,"v":"Mixed Cryoglobulinemia Often HCV-associate Cryoglobulins Immune complex"},{"k":"p","l":2,"v":"d HCV antibodies (Option D deposits Purpura ruled out) Small vessel vasculitis Arthralgias"},{"k":"p","l":1,"v":"Vasculitis Type Examples of Diseases"},{"k":"p","l":1,"v":"Granulomatous Granulomatosis with Polyangiitis"},{"k":"p","l":2,"v":"Churg-Strauss Syndrome Sarcoidosis Behcet's Disease (granulomatous form)"},{"k":"p","l":1,"v":"Non-Granulomatous Microscopic Polyangiitis"},{"k":"p","l":2,"v":"Polyarteritis Nodosa Henoch-Schonlein Purpura Takayasu Arteritis Giant Cell Arteritis Kawasaki Disease"},{"k":"p","l":1,"v":"Necrotizing Granulomatosis with Polyangiitis"},{"k":"p","l":2,"v":"Microscopic Polyangiitis Polyarteritis Nodosa (PAN) Churg-Strauss Syndrome Henoch-Schönlein Purpura"},{"k":"p","l":1,"v":"Non-Necrotizing Takayasu Arteritis"},{"k":"p","l":2,"v":"Giant Cell Arteritis Kawasaki Disease Sarcoidosis (rare vasculitis involvement)"}]},{"n":9,"q":"A 25-year-old man from Turkey presents with recurrent painful oral ulcers, genital ulcers, and bilateral red eyes. Examination reveals bilateral anterior uveitis and erythema nodosum on his legs. After the needle prick, he develops an erythematous papule in 48 hours. Laboratory studies show elevated IL-1, TNF-a, and increased neutrophil activity. Which of the following best describes the pathogenesis and clinical features of this condition?","o":[{"t":"ANCA-mediated vasculitis with small vessel involvement"},{"t":"Auto-inflammatory vasculitis with T-cell mediated immunity and neutrophilic inflammation"},{"t":"Antibody-mediated disease with preferential renal involvement"},{"t":"IgA-mediated vasculitis with predominant GI manifestations"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Auto-inflammatory vasculitis with T-cell mediated immunity and neutrophilic inflammation"},{"k":"h","l":0,"v":"Explanation: This patient presents with classic features of Behcet's Disease:"},{"k":"b","l":0,"v":"Young adult male from Turkey (along the \"Silk Route\")"},{"k":"b","l":0,"v":"Mucocutaneous manifestations (oral/genital ulcers)"},{"k":"b","l":0,"v":"Ocular involvement (uveitis)"},{"k":"b","l":0,"v":"Positive pathergy test (Abnormal skin reaction to minor trauma, which is characteristic of the disease)"},{"k":"b","l":0,"v":"Skin lesions (erythema nodosum)"},{"k":"p","l":0,"v":"The pathogenesis of Behcet’s Disease involves auto-inflammatory vasculitis with T-cell mediated immunity and neutrophilic inflammation."},{"k":"p","l":0,"v":"Behcet’s Disease- Pathogenesis and Clinical Features:"},{"k":"p","l":0,"v":"Category Features Clinical Significance"},{"k":"p","l":0,"v":"Pathogenesis T-cell mediated immunity Auto-inflammatory rather than"},{"k":"p","l":2,"v":"Th1 cell activation autoimmune Elevated cytokines (IL-1, TNF-a) Affects vessels of all sizes Neutrophilic vasculitis Treatment targets inflammation No specific autoantibodies"},{"k":"p","l":0,"v":"Mucocutaneous Oral ulcers (97-99%) Often initial presentation"},{"k":"p","l":2,"v":"Genital ulcers (>80%) Oral ulcers heal without scarring Erythema nodosum Genital ulcers leave scars Pathergy reaction"},{"k":"p","l":0,"v":"Major Organ Involvement Uveitis (>50%) More severe in males"},{"k":"p","l":2,"v":"Vascular (25%) Ocular disease can cause blindness Neurologic (5-10%) Vascular involvement can be fatal Arthritis (non-erosive)"},{"k":"img","v":8868},{"k":"p","l":0,"v":"ANCA-mediated vasculitis with small vessel involvement (Option A): ANCA-associated vasculitides, such as granulomatosis with polyangiitis , typically involve the respiratory tract and kidneys and do not present with recurrent oral and genital ulcers or a positive pathergy test."},{"k":"p","l":0,"v":"Antibody-mediated disease with preferential renal involvement (Option C): This option suggests diseases like lupus nephritis, which involves antibody-mediated kidney damage. However, renal involvement is not a primary feature of Behçet's disease."},{"k":"p","l":0,"v":"IgA-mediated vasculitis with predominant GI manifestations (Option D): IgA vasculitis (Henoch-Schönlein purpura) often presents with palpable purpura, GI symptoms, and renal involvement, which are inconsistent with the features seen in this patient."}]},{"n":10,"q":"A 30-year-old man presents with recurrent oral ulcers, genital ulcers, and bilateral uveitis. He develops pustules 48 hours after the needle prick. Further examination reveals erythema nodosum and non-erosive arthritis of the knees. Based on clinical criteria, Behcet's Disease is diagnosed. Which of the following represents the most appropriate initial management strategy?","o":[{"t":"High-dose steroids alone for all manifestations"},{"t":"Targeted therapy based on organ involvement: colchicine for mucocutaneous, topical steroids for anterior uveitis"},{"t":"Immediate cyclophosphamide for all patients"},{"t":"Anticoagulation alone for all manifestations"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Targeted therapy based on organ involvement: colchicine for mucocutaneous, topical steroids for anterior uveitis"},{"k":"h","l":0,"v":"Explanation: This patient presents with various manifestations of Behcet's Disease requiring organ-specific management."},{"k":"p","l":0,"v":"Behcet’s Disease- Diagnosis and Management:"},{"k":"p","l":0,"v":"Diagnosis"},{"k":"p","l":0,"v":"Diagnostic Criteria Two Points Each: ‡3 points needed for diagnosis (ITR-ICBD) Genital aphthosis"},{"k":"p","l":2,"v":"Ocular lesions One Point Each: Oral aphthosis Skin lesions Vascular manifestations Positive pathergy"},{"k":"p","l":0,"v":"Laboratory Findings Non-specific inflammation markers Helps rule out other conditions"},{"k":"p","l":2,"v":"No specific autoantibodies ESR, CRP elevation Leukocytosis"},{"k":"p","l":0,"v":"Required Investigations Ophthalmologic examination Confirms involvement and monitors"},{"k":"p","l":2,"v":"Pathergy test complications Skin biopsy if needed Imaging, based on symptoms"},{"k":"p","l":0,"v":"Treatment"},{"k":"p","l":0,"v":"Mucocutaneous Colchicine 1-2mg/day Refractory: Systemic steroids, Treatment Topical steroids azathioprine"},{"k":"p","l":2,"v":"Topical sucralfate"},{"k":"p","l":0,"v":"Ocular Treatment Anterior: Topical steroids Refractory: TNF inhibitors"},{"k":"p","l":2,"v":"Posterior: Steroids + azathioprine"},{"k":"p","l":0,"v":"Major Organ Involvemen Vascular: High-dose steroids + Requires aggressive therapy and t cyclophosphamide monitoring"},{"k":"p","l":2,"v":"Neurologic: High-dose steroids + immunosuppression"},{"k":"p","l":0,"v":"High-dose steroids alone for all manifestations (Option A) is incorrect because treatment needs to be targeted to specific organ involvement rather than blanket steroid therapy."},{"k":"p","l":0,"v":"Immediate cyclophosphamide for all patients (Option C) is incorrect because cyclophosphamide is reserved for severe manifestations like neurologic or major vascular involvement."},{"k":"p","l":0,"v":"Anticoagulation alone for all manifestations (Option D) is incorrect because anticoagulation alone is insufficient and immunosuppression is the mainstay of therapy."}]},{"n":11,"q":"A 4-year-old Asian boy presents with 6 days of fever, bilateral conjunctival injection without exudate, strawberry tongue, and cervical lymphadenopathy >1.5 cm. On day 7, he develops erythema of palms and soles. Laboratory studies show elevated TNF-a and pro-BNP. Which of the following best describes the pathogenesis of this condition?","o":[{"t":"Direct viral invasion of coronary vessels with late thrombosis"},{"t":"Immune-mediated medium vessel vasculitis with coronary artery predilection"},{"t":"Bacterial toxin-mediated endothelial damage with early thrombosis"},{"t":"Primary autoimmune arteritis with small vessel involvement"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Immune-mediated medium vessel vasculitis with coronary artery predilection"},{"k":"h","l":0,"v":"Explanation: This patient's clinical features are highly suggestive of Kawasaki Disease, presenting with prolonged fever for 6 days accompanied by classic mucocutaneous findings including bilateral non-exudative conjunctivitis, strawberry tongue, unilateral cervical lymphadenopathy >1.5cm, and erythema of palms and soles."},{"k":"p","l":0,"v":"Pathogenesis:"},{"k":"b","l":0,"v":"TNF-a elevation"},{"k":"b","l":0,"v":"IL-1, 4, 6 activation"},{"k":"b","l":0,"v":"Matrix metalloproteinases (MMP3, MMP9) release"},{"k":"p","l":0,"v":"Kawasaki Disease:"},{"k":"p","l":0,"v":"Category Features Clinical Significance Diagnostic Criteria Fever for >= 5 days + 4 out of 5 Needs 4/5 criteria + fever ‡5 days (CREAM) criteria (CREAM)"},{"k":"p","l":2,"v":"C : Conjunctivitis (bilateral, non-purulent) R : Rash (polymorphous) E : Extremity changes (swelling, redness, peeling) A : Adenopathy (cervical >1.5cm) M : Mucosal changes (strawberry tongue)"},{"k":"p","l":0,"v":"High-Risk Features - Male gender Higher risk of coronary complications"},{"k":"p","l":2,"v":"- Age <1 year - Asian ethnicity - Fever >8 days - High pro-BNP"},{"k":"p","l":0,"v":"Cardiac Involvement - Coronary artery aneurysms 15-25% develop aneurysms if"},{"k":"p","l":2,"v":"- Myocarditis untreated - Pericardial effusion"},{"k":"p","l":0,"v":"Direct viral invasion of coronary vessels with late thrombosis (Option A) is incorrect because Kawasaki disease is not a direct viral invasion, but rather an immune response to a possible infectious trigger."},{"k":"p","l":0,"v":"Bacterial toxin-mediated endothelial damage with early thrombosis (Option C) is incorrect because it's not bacterial toxin-mediated and early thrombosis isn't typical."},{"k":"p","l":0,"v":"Primary autoimmune arteritis with small vessel involvement (Option D) is incorrect because it primarily affects medium vessels, not small vessels."}]},{"n":12,"q":"A 3-year-old boy presents with 6 days of fever, bilateral conjunctivitis, strawberry tongue, and polymorphous rash. Initial labs show elevated CRP, ESR, and thrombocytosis. Which of the following represents the most appropriate initial diagnostic test and treatment strategy?","o":[{"t":"Blood culture and broad-spectrum antibiotics"},{"t":"Echocardiogram and IVIG 2g/kg plus high-dose aspirin"},{"t":"Throat culture and penicillin"},{"t":"Viral panel and supportive care"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Echocardiogram and IVIG 2g/kg plus high-dose aspirin"},{"k":"h","l":0,"v":"Explanation: This patient presents with classic features of Kawasaki Disease (KD) including:"},{"k":"b","l":0,"v":"Fever for >= 5 days + 4 out of 5 criteria (CREAM)"},{"k":"b","l":0,"v":"C : Conjunctivitis (bilateral, non-purulent)"},{"k":"b","l":0,"v":"R : Rash (polymorphous)"},{"k":"b","l":0,"v":"E : Extremity changes (swelling, redness, peeling)"},{"k":"b","l":0,"v":"A : Adenopathy (cervical >1.5cm)"},{"k":"b","l":0,"v":"M : Mucosal changes (strawberry tongue)"},{"k":"p","l":0,"v":"Echocardiogram and IVIG 2g/kg plus high-dose aspirin (Option B) is the correct treatment because:"},{"k":"p","l":0,"v":"Kawasaki Disease- Diagnosis & Treatment:"},{"k":"p","l":1,"v":"Category Details Clinical Significance Initial Diagnostic 1. Echocardiogram - Echo: baseline coronary status Tests 2. Labs: - ‡3 supplemental labs support"},{"k":"p","l":2,"v":"- CRP (typically >3 mg/dL ) diagnosis in incomplete KD - ESR (typically >40 mm/hr ) - Helps differentiate from other - CBC: Leukocytosis >15,000 febrile illnesses - Platelets >450,000 - Albumin <3.0 g/dL - E levated ALT - Sterile pyuria"},{"k":"p","l":1,"v":"Initial Treatment 1 . IVIG: - Reduces aneurysm risk"},{"k":"p","l":2,"v":"- 2g/kg single dose - IVIG resistance in 15-20% - Within 10 days of fever - Time-sensitive intervention 2. Aspirin: - High-dose (80-100mg/kg/d) - Until afebrile 48h"},{"k":"p","l":1,"v":"Additional Therapy - Second IVIG dose if needed - Based on response"},{"k":"p","l":2,"v":"- Steroids in high-risk cases - Risk stratification - Infliximab for refractory cases - Prevent complications - Anticoagulation if aneurysms"},{"k":"p","l":1,"v":"Follow-up - Echo at 2 weeks - Monitor for aneurysms"},{"k":"p","l":2,"v":"- Echo at 6-8 weeks - Assess treatment response - Low-dose aspirin - Prevent thrombosis (3-5mg/kg/d) - Long-term cardiac monitoring"},{"k":"p","l":0,"v":"Blood culture and broad-spectrum antibiotics (Option A) is incorrect because bacterial infection is not the primary concern and antibiotics are not indicated."},{"k":"p","l":0,"v":"Throat culture and penicillin (Option C) is incorrect because streptococcal infection is not the likely diagnosis given the constellation of findings."},{"k":"p","l":0,"v":"Viral panel and supportive care (Option D) is incorrect because Kawasaki disease requires specific treatment, not just supportive care."}]},{"n":13,"q":"A 40-year-old man with a history of asthma presents with worsening dyspnea, peripheral neuropathy, and palpable purpura on his lower limbs. He also has a history of sinusitis. Blood tests reveal marked eosinophilia and a positive p-ANCA. What is the most likely diagnosis?","o":[{"t":"Wegener's Granulomatosis"},{"t":"Churg-Strauss Syndrome"},{"t":"Microscopic Polyangiitis"},{"t":"Polyarteritis Nodosa"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Churg-Strauss Syndrome"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Churg-Strauss Syndrome aka Eosinophilic Granulomatosis with Polyangiitis (EGPA) is most commonly associated with a history of asthma , marked eosinophilia , and systemic vasculitis involving the skin, lungs, nerves, and sinuses. The positive p-ANCA result further supports thediagnosis"},{"k":"b","l":0,"v":"Prodromal phase : Characterized by allergic rhinitis , nasal polyposis , and late-onset asthma , often difficult to control."},{"k":"b","l":0,"v":"Acute presentation : Triad : Skin lesions (purpura or nodules), asymmetric mononeuritis multiplex , and eosinophilia . Pulmonary involvement : Pulmonary infiltrates, pleural/pericardial effusions, and serositis may be seen. Abdominal symptoms in 50% due to mesenteric vasculitis ."},{"k":"b","l":0,"v":"Triad : Skin lesions (purpura or nodules), asymmetric mononeuritis multiplex , and eosinophilia ."},{"k":"b","l":0,"v":"Pulmonary involvement : Pulmonary infiltrates, pleural/pericardial effusions, and serositis may be seen."},{"k":"b","l":0,"v":"Abdominal symptoms in 50% due to mesenteric vasculitis ."},{"k":"b","l":0,"v":"Triad : Skin lesions (purpura or nodules), asymmetric mononeuritis multiplex , and eosinophilia ."},{"k":"b","l":0,"v":"Pulmonary involvement : Pulmonary infiltrates, pleural/pericardial effusions, and serositis may be seen."},{"k":"b","l":0,"v":"Abdominal symptoms in 50% due to mesenteric vasculitis ."},{"k":"p","l":0,"v":"Lab Findings:"},{"k":"b","l":0,"v":"Eosinophilia ."},{"k":"b","l":0,"v":"Elevated ESR and CRP ."},{"k":"b","l":0,"v":"ANCA (usually p-ANCA ) may be positive in up to 60%"},{"k":"p","l":0,"v":"Eosinophilia ."},{"k":"p","l":0,"v":"Elevated ESR and CRP ."},{"k":"p","l":0,"v":"ANCA (usually p-ANCA ) may be positive in up to 60%"},{"k":"p","l":0,"v":"Biopsy:"},{"k":"b","l":0,"v":"Small-vessel vasculitis with eosinophilic infiltration of the vessel walls."},{"k":"p","l":0,"v":"Small-vessel vasculitis with eosinophilic infiltration of the vessel walls."},{"k":"p","l":0,"v":"Management:"},{"k":"b","l":0,"v":"Acute : High-dose glucocorticoids and cyclophosphamide."},{"k":"b","l":0,"v":"Maintenance : Low-dose glucocorticoids and azathioprine, methotrexate, or mycophenolate mofetil (MMF)."},{"k":"p","l":0,"v":"Wegener's Granulomatosis (Granulomatosis with Polyangiitis) (Option A) : This vasculitis affects the upper and lower respiratory tract and kidneys but is more commonly associated with c-ANCA positivity, rather than p-ANCA. Additionally, patients with Wegener's typically do not have prominent eosinophilia, which is a hallmark of EGPA."},{"k":"p","l":0,"v":"Microscopic Polyangiitis (MPA) (Option C): This small-vessel vasculitis is typically associated with p-ANCA and necrotizing vasculitis, affecting organs like the kidneys and lungs. However, MPA does not present with the asthma or eosinophilia characteristic of EGPA. It is also not typically associated with palpable purpura."},{"k":"p","l":0,"v":"Polyarteritis Nodosa (PAN) (Option D) : PAN is a medium-vessel vasculitis that affects arteries, commonly leading to renal, gastrointestinal, and musculoskeletal involvement, but PAN does not typically present with eosinophilia, asthma, or p-ANCA. It is also not associated with the characteristic findings of pulmonary infiltrates seen in EGPA."}]},{"n":14,"q":"Which of the following vasculitis syndromes is not classified as an ANCA-associated vasculitis according to the Chapel Hill Classification?","o":[{"t":"Granulomatosis with Polyangiitis (GPA)"},{"t":"Microscopic Polyangiitis (MPA)"},{"t":"Eosinophilic Granulomatosis with Polyangiitis (EGPA)"},{"t":"Polyarteritis Nodosa (PAN)"}],"a":[3],"s":[{"k":"p","l":0,"v":"Correct answer: D) Polyarteritis Nodosa (PAN)"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Polyarteritis Nodosa is a medium vessel vasculitis, according to the Revised Chapel Hill classification of vasculitis syndromes"},{"k":"p","l":0,"v":"Revised Chapel Hill classification of vasculitis syndromes"},{"k":"p","l":0,"v":"Large vessel vasculitis Takayasu arteritis"},{"k":"p","l":2,"v":"Giant cell arteritis"},{"k":"p","l":0,"v":"Medium vessel vasculitis Takayasu arteritis"},{"k":"p","l":2,"v":"Giant cell arteritis"},{"k":"p","l":0,"v":"Small vessel vasculitis (SVV) Antineutrophil cytoplasmic antibody (ANCA)–associated"},{"k":"p","l":2,"v":"vasculitis Microscopic polyangiitis Granulomatosis with polyangiitis (Wegener’s) Eosinophilic granulomatosis with polyangiitis (Churg-Strauss) Immune complex SVV Anti-glomerular basement membrane (anti-GBM) disease Cryoglobulinemic vasculitis IgA vasculitis (Henoch-Schönlein)"},{"k":"p","l":2,"v":"Hypocomplementemic urticarial vasculitis (anti-C1q vasculitis)"},{"k":"p","l":0,"v":"Variable vessel vasculitis Behcet’s disease"},{"k":"p","l":2,"v":"Cogan’s syndrome"},{"k":"p","l":0,"v":"Single-organ vasculitis Cutaneous leukocytoclastic angiitis"},{"k":"p","l":2,"v":"Cutaneous arteritis Primary central nervous system vasculitis Isolated aortitis"},{"k":"p","l":0,"v":"Vasculitis associated with systemic disease Lupus vasculitis"},{"k":"p","l":2,"v":"Rheumatoid vasculitis Sarcoid vasculitis"},{"k":"p","l":0,"v":"Vasculitis associated with probable etiology Hepatitis C virus–associated cryoglobulinemic vasculitis"},{"k":"p","l":2,"v":"Hepatitis B virus–associated vasculitis Syphilis-associated aortitis Drug-associated immune complex vasculitis Drug-associated ANCA-associated vasculitis Cancer-associated vasculitis"}]}]);
